def search(arr):
    lo, hi = 0, len(arr) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        # Pairs always start at even indices; align mid to an even index.
        if mid % 2 == 1:
            mid -= 1
        if arr[mid] == arr[mid + 1]:
            # Pair is intact, the single element is to the right.
            lo = mid + 2
        else:
            # Pair is broken, the single element is at mid or to the left.
            hi = mid
    return arr[lo]
```

