def count_char_position(s: str) -> int:
    """
    Count characters whose lowercase form matches the English alphabet letter
    at the same 1-based position (a=1, b=2, ..., z=26).

    Non-letters never match, and positions beyond 26 have no alphabet letter.
    """
    return sum(
        1
        for i, ch in enumerate(s[:26])
        if ch.lower() == chr(ord("a") + i)
    )
```

